import React, { useState } from 'react';
import axios from 'axios';

function HealthRiskForm() {
    const [location, setLocation] = useState('');
    const [healthRisks, setHealthRisks] = useState([]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const response = await axios.post('/api/health/weather-health-risk', { location });
            setHealthRisks(response.data.healthRisks);
        } catch (error) {
            console.error("Error fetching health risks:", error);
        }
    };

    return (
        <div>
            <h2>Weather-Based Health Risk Check</h2>
            <form onSubmit={handleSubmit}>
                <input type="text" value={location} onChange={(e) => setLocation(e.target.value)} placeholder="Enter location" />
                <button type="submit">Check Health Risks</button>
            </form>
            <div>
                {healthRisks.length > 0 && <h3>Health Risks:</h3>}
                {healthRisks.map((risk, index) => (
                    <p key={index}>{risk}</p>
                ))}
            </div>
        </div>
    );
}

export default HealthRiskForm;
